-- 0005 — seed the RBAC vocabulary and the default grants.
--
-- GENERATED by `npm run seed:rbac` from src/server/permissions.ts.
-- Do not edit by hand; regenerate. tests/rbac-seed.test.ts checks that
-- this file still matches the TypeScript, so an edit to one without the
-- other fails the suite.
--
-- Idempotent, so it can be pasted into phpMyAdmin when SSH is unavailable
-- — which it will be. Note what that means, though: this is a *seed*. Once
-- it has run the database is authoritative, because an administrator may
-- adjust grants without a deploy. Re-running it restores the defaults for
-- anything that has been removed.

-- The permission vocabulary. Also a closed union in TypeScript, so a
-- misspelled code is a compile error rather than a check that never matches.
ON DUPLICATE KEY UPDATE label_en = VALUES(label_en), domain = VALUES(domain);

-- The roles. Five from spec section 8.3, plus `cashier` and
-- `membership_approver`: the printed form carries a cashier block with its
-- own signature, and somebody must *grant* membership. One officer doing
-- both verification and approval collapses the separation of duties that
-- the checklist, the staff signature, the cashier signature and the
-- approval block exist to create.
ON DUPLICATE KEY UPDATE label_en = VALUES(label_en), is_system = VALUES(is_system);

-- Super administrator: every permission, selected from the table rather than
-- enumerated, so this statement stays correct as permissions are added.
-- A later migration that adds one should repeat it.
SELECT 'super_admin', code FROM permissions;

